import pandas as pd
import json
from datetime import datetime

# --- Configuration ---
FILES = {
    'a': '/data/source_a/users.json',  # Priority 1
    'b': '/data/source_b/users.csv',   # Priority 2
    'c': '/data/source_c/users.parquet' # Priority 3
}

OUTPUT_MERGED = '/app/merged_users.parquet'
OUTPUT_CONFLICT = '/app/conflicts.json'

# Mappings: Old Field: Unified Name
FIELD_MAP = {
    'user_id': 'user_id', 'id': 'user_id', 'userId': 'user_id',
    'email': 'email', 'email_address': 'email',
    'full_name': 'name', 'name': 'name', 'userName': 'name',
    'registration_date': 'created_date', 'created_at': 'created_date', 'joined': 'created_date'
}

# List of unified fields and their expected types
UNIFIED_FIELDS = ['user_id', 'name', 'email', 'created_date']

def load_data(file_path, source_name):
    """Loads data from various formats and standardizes column names."""
    print(f"\n--- Loading data from {source_name} ({file_path}) ---")
    try:
        if file_path.endswith('.json'):
            df = pd.read_json(file_path)
        elif file_path.endswith('.csv'):
            df = pd.read_csv(file_path)
        elif file_path.endswith('.parquet'):
            df = pd.read_parquet(file_path)
        else:
            raise ValueError(f"Unsupported file format for {file_path}")

        # Standardize column names
        col_map = {}
        existing_cols = [col for col in df.columns]
        for col in existing_cols:
            standardized_col = next((k for k in FIELD_MAP if col.lower() == k.lower() or k.lower() in col.lower()), col)
            if standardized_col != col: # Check if a mapping was applied
                col_map[col] = standardized_col
            else:
                col_map[col] = col

        df.rename(columns=col_map, inplace=True)
        return df
    except Exception as e:
        print(f"[ERROR] Could not load data from {source_name}: {e}")
        return pd.DataFrame()

def process_source(df, source_name):
    """Extracts relevant columns, enforces data types, and handles date formatting."""
    if df.empty: return pd.DataFrame()

    # Keep only the unified columns
    df = df[[col for col in df.columns if col in UNIFIED_FIELDS]].copy()

    # Basic cleaning and type enforcement
    for field in UNIFIED_FIELDS:
        if field in df.columns:
            if field == 'user_id':
                df[field] = pd.to_numeric(df[field], errors='coerce').astype('Int64').astype(str) # Ensure consistent string representation for merging
            elif field == 'created_date':
                # Attempt to parse date, handling various formats
                df[field] = pd.to_datetime(df[field], errors='coerce').dt.strftime('%Y-%m-%d')
            else:
                df[field] = df[field].astype(str).str.strip()

    return df.dropna(subset=['user_id']).reset_index(drop=True)

def merge_and_report(dfs):
    """Merges all dataframes based on user_id and tracks conflicts."""
    print("\n--- Starting Merge and Conflict Resolution ---")

    # 1. Create a master dictionary mapping user_id to sources for comprehensive comparison
    user_data = {} # {user_id: {'source_a': {...}, 'source_b': {...}, 'source_c': {...}}}

    # Initialize with dummy structures for easier comparison
    for source_name, df in dfs.items():
        for _, row in df.iterrows():
            user_id = row['user_id']
            if user_id not in user_data:
                user_data[user_id] = {
                    'user_id': user_id, 
                    'source_a': {}, 'source_b': {}, 'source_c': {},
                    'original_rows': [] # To store the actual data points for merging
                }

            # Store the row data, keeping track of which source it came from
            row_dict = row.to_dict()
            user_data[user_id][source_name] = row_dict
            user_data[user_id]['original_rows'].append(row_dict)

    merged_records = []
    conflict_report_list = []

    # 2. Iterate over unique user IDs and apply merge logic (A > B > C)
    for user_id, data in user_data.items():
        merged_row = {'user_id': user_id}
        conflict_details = []

        # Priority order: A, B, C
        sources_in_priority_order = ['a', 'b', 'c']

        for field in UNIFIED_FIELDS[1:]:
            field_values = {}
            values_present = [source for source in sources_in_priority_order if source in data and data[source].get(field) is not None]

            if not values_present: continue # Skip if field is missing entirely

            # Gather all present values for conflict checking
            all_values = []
            for source in sources_in_priority_order:
                if source in data and data[source].get(field) is not None:
                    val = data[source][field]
                    all_values.append(val)
                    field_values[source] = val

            # Check for conflicts
            unique_values = set(all_values)
            is_conflict = len(unique_values) > 1

            # Determine selected value based on priority (A > B > C)
            selected_value = None
            for source in sources_in_priority_order:
                if source in data and data[source].get(field) is not None:
                    selected_value = data[source][field]
                    break # Found the highest priority non-null value

            # Add to merged row
            merged_row[field] = selected_value

            # Record conflict details if necessary
            if is_conflict:
                conflict_report_list.append({
                    "user_id": user_id,
                    "field": field,
                    "values": {
                        "source_a": field_values['a'] if 'a' in field_values else None,
                        "source_b": field_values['b'] if 'b' in field_values else None,
                        "source_c": field_values['c'] if 'c' in field_values else None
                    },
                    "selected": selected_value
                })

        merged_records.append(merged_row)

    # 3. Generate Output Files

    # Merged Data (Parquet)
    df_merged = pd.DataFrame(merged_records)
    df_merged.to_parquet(OUTPUT_MERGED, index=False)
    print(f"\n[SUCCESS] Merged dataset written to {OUTPUT_MERGED}")

    # Conflict Report (JSON)
    report = {
        "total_conflicts": len(conflict_report_list),
        "conflicts": conflict_report_list
    }
    with open(OUTPUT_CONFLICT, 'w') as f:
        json.dump(report, f, indent=2)
    print(f"[SUCCESS] Conflict report written to {OUTPUT_CONFLICT}")

if __name__ == '__main__':
    # 1. Load and standardize data from all sources
    df_a = load_data(FILES['a'], 'source_a')
    df_b = load_data(FILES['b'], 'source_b')
    df_c = load_data(FILES['c'], 'source_c')

    # 2. Process the loaded data (clean types, enforce structure)
    df_a_proc = process_source(df_a, 'source_a')
    df_b_proc = process_source(df_b, 'source_b')
    df_c_proc = process_source(df_c, 'source_c')

    # 3. Merge and write outputs
    dfs = {'a': df_a_proc, 'b': df_b_proc, 'c': df_c_proc}
    merge_and_report(dfs)

